"use client";

import React from "react";
import Link from "next/link";

/**
 * Minimal secondary "← Back to Homepage" link under the nav bar.
 */
export function BackLink() {
    return (
        <div className="pt-24 pb-2 px-8 relative z-10">
            <Link
                href="/"
                className="inline-flex items-center gap-2 text-sm text-gray-500 hover:text-gray-300 transition-colors tracking-wide group"
            >
                <span className="transform transition-transform group-hover:-translate-x-1">←</span>
                Back to Homepage
            </Link>
        </div>
    );
}
